#!/usr/bin/env python3
"""Validate IRG incident records and print coverage statistics.

Usage, from the repository root:

    python project/validate.py                 # validate everything in project/corpus/
    python project/validate.py path/to/rec.json

Deliberately dependency-free: it implements only the small subset of JSON Schema that
schema.json uses, so a volunteer can run it with a bare Python 3.9+ install.

NOTE: written 2026-11-16 and not yet executed against a real corpus (there isn't one yet).
Treat the first run as a test of this script as much as of the data.
"""

from __future__ import annotations

import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Dict, List

HERE = Path(__file__).resolve().parent
SCHEMA_PATH = HERE / "schema.json"
CORPUS_DIR = HERE / "corpus"

# Records with these statuses are specifications/illustrations, not evidence.
NON_EVIDENTIAL_STATUSES = {"synthetic-example", "withdrawn"}
# Only these may appear in any reported statistic.
REPORTABLE_STATUSES = {"double-coded", "published"}


# --------------------------------------------------------------------------- #
# Minimal JSON Schema subset validator
# --------------------------------------------------------------------------- #

TYPE_MAP = {
    "object": dict,
    "array": list,
    "string": str,
    "integer": int,
    "number": (int, float),
    "boolean": bool,
}


def validate_node(value: Any, schema: Dict[str, Any], path: str) -> List[str]:
    """Return a list of human-readable error strings for `value` against `schema`."""
    errors: List[str] = []

    expected = schema.get("type")
    if expected:
        py_type = TYPE_MAP.get(expected)
        # bool is a subclass of int in Python; reject it where a number is wanted.
        if py_type and (
            not isinstance(value, py_type)
            or (expected in ("integer", "number") and isinstance(value, bool))
        ):
            errors.append(f"{path}: expected {expected}, got {type(value).__name__}")
            return errors  # further checks would be meaningless

    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: {value!r} not one of {schema['enum']}")

    if isinstance(value, str):
        pattern = schema.get("pattern")
        if pattern and not re.search(pattern, value):
            errors.append(f"{path}: {value!r} does not match /{pattern}/")
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(
                f"{path}: length {len(value)} is below minimum {schema['minLength']}"
            )
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(
                f"{path}: length {len(value)} exceeds maximum {schema['maxLength']}"
            )

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(f"{path}: {value} is below minimum {schema['minimum']}")
        if "maximum" in schema and value > schema["maximum"]:
            errors.append(f"{path}: {value} exceeds maximum {schema['maximum']}")

    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(f"{path}: needs at least {schema['minItems']} item(s)")
        if schema.get("uniqueItems"):
            seen = [json.dumps(v, sort_keys=True) for v in value]
            if len(set(seen)) != len(seen):
                errors.append(f"{path}: contains duplicate items")
        item_schema = schema.get("items")
        if item_schema:
            for i, item in enumerate(value):
                errors += validate_node(item, item_schema, f"{path}[{i}]")

    if isinstance(value, dict):
        props = schema.get("properties", {})
        for field in schema.get("required", []):
            if field not in value:
                errors.append(f"{path}: missing required field {field!r}")
        if schema.get("additionalProperties") is False:
            for key in value:
                if key not in props:
                    errors.append(f"{path}: unexpected field {key!r}")
        for key, sub in value.items():
            if key in props:
                errors += validate_node(sub, props[key], f"{path}.{key}" if path else key)

    return errors


# --------------------------------------------------------------------------- #
# Project-specific consistency checks
# --------------------------------------------------------------------------- #

def consistency_checks(rec: Dict[str, Any]) -> List[str]:
    """Checks the schema cannot express. Returns warnings, not hard failures."""
    warnings: List[str] = []
    rid = rec.get("id", "<no id>")
    status = rec.get("record_status")

    if status == "double-coded" and not rec.get("second_coder"):
        warnings.append(f"{rid}: marked double-coded but no second_coder named")

    if status in REPORTABLE_STATUSES and rec.get("source_strength") == "contested":
        warnings.append(
            f"{rid}: contested source strength but status {status!r} — "
            "a contested event should not enter reported statistics without a note"
        )

    if rec.get("primary_class") == "A10" and not rec.get("secondary_classes"):
        warnings.append(
            f"{rid}: near-miss (A10) should carry the averted class as a secondary"
        )

    for cls in rec.get("secondary_classes", []):
        if cls == rec.get("primary_class"):
            warnings.append(f"{rid}: {cls} listed as both primary and secondary")

    # The counterfactual must be reasoned from Part B, so it has to mention it.
    justification = (rec.get("counterfactual_justification") or "").lower()
    if justification and not any(
        token in justification
        for token in ("detect", "lag", "incentive", "clock", "locus", "disclos")
    ):
        warnings.append(
            f"{rid}: counterfactual_justification does not reference any Part B dimension"
        )

    # A developer-internal incident disclosed within a day is unusual; worth a second look.
    if (
        rec.get("detection_locus") == "developer-internal-only"
        and rec.get("disclosure_lag") == "<24h"
        and rec.get("disclosure_incentive") in ("adverse", "strongly-adverse")
    ):
        warnings.append(
            f"{rid}: adverse-incentive internal incident disclosed in <24h — "
            "verify the dates against the source"
        )

    if not rec.get("sources"):
        warnings.append(f"{rid}: no sources — record must not be published")

    return warnings


# --------------------------------------------------------------------------- #
# Statistics
# --------------------------------------------------------------------------- #

def report_statistics(records: List[Dict[str, Any]]) -> None:
    usable = [r for r in records if r.get("record_status") in REPORTABLE_STATUSES]
    print("\n--- Coverage ---")
    print(f"records on disk        : {len(records)}")
    print(f"usable for statistics  : {len(usable)}  (double-coded or published)")

    excluded = Counter(
        r.get("record_status") for r in records if r.get("record_status") not in REPORTABLE_STATUSES
    )
    for status, n in sorted(excluded.items(), key=lambda kv: str(kv[0])):
        print(f"  excluded ({status}): {n}")

    if not usable:
        print("\nNo usable records yet — no statistics to report.")
        print("This is the expected state until the first double-coded incidents land.")
        return

    def dist(field: str) -> None:
        counts = Counter(r.get(field) for r in usable)
        print(f"\n{field}:")
        for key, n in counts.most_common():
            print(f"  {str(key):<26} {n:>4}  ({n / len(usable):.0%})")

    for field in (
        "primary_class",
        "detection_locus",
        "discovery_lag",
        "disclosure_lag",
        "disclosure_incentive",
        "clock_start",
        "counterfactual_catch",
        "source_strength",
    ):
        dist(field)

    # H1: are high-control-relevance incidents disproportionately opaque?
    print("\n--- H1 check: control-relevance vs detection locus ---")
    table: Dict[int, Counter] = defaultdict(Counter)
    for r in usable:
        cr = r.get("severity", {}).get("control_relevance")
        table[cr][r.get("detection_locus")] += 1
    for cr in sorted(k for k in table if k is not None):
        row = ", ".join(f"{k}={v}" for k, v in table[cr].most_common())
        print(f"  control_relevance {cr}: {row}")

    print("\n--- H4 check: near-miss representation ---")
    near = sum(
        1 for r in usable
        if r.get("primary_class") == "A10" or "A10" in (r.get("secondary_classes") or [])
    )
    print(f"  near-misses: {near} of {len(usable)} ({near / len(usable):.0%})")

    print("\n--- Double-coding disagreements ---")
    disagreements = Counter()
    for r in usable:
        for d in r.get("disagreements") or []:
            disagreements[d.get("field")] += 1
    if not disagreements:
        print("  none recorded")
        print("  NOTE: zero disagreements across many records usually means the coders were")
        print("  not independent. Check the process before believing this number.")
    else:
        for field, n in disagreements.most_common():
            print(f"  {field:<30} {n:>4}")


# --------------------------------------------------------------------------- #

def load_records(paths: List[Path]) -> List[tuple]:
    out = []
    for p in sorted(paths):
        try:
            out.append((p, json.loads(p.read_text(encoding="utf-8"))))
        except json.JSONDecodeError as exc:
            print(f"FAIL {p.name}: not valid JSON — {exc}")
            out.append((p, None))
    return out


def main(argv: List[str]) -> int:
    if not SCHEMA_PATH.exists():
        print(f"Cannot find schema at {SCHEMA_PATH}")
        return 2
    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))

    if len(argv) > 1:
        paths = [Path(a) for a in argv[1:]]
    else:
        if not CORPUS_DIR.exists():
            print(f"No corpus directory at {CORPUS_DIR} — nothing to validate.")
            return 0
        paths = list(CORPUS_DIR.glob("*.json"))

    if not paths:
        print("No records found. Expected while the corpus is still empty.")
        return 0

    loaded = load_records(paths)
    hard_failures = 0
    all_warnings: List[str] = []
    records: List[Dict[str, Any]] = []
    seen_ids: Dict[str, str] = {}

    for path, rec in loaded:
        if rec is None:
            hard_failures += 1
            continue
        errors = validate_node(rec, schema, "")
        if errors:
            hard_failures += 1
            print(f"\nFAIL {path.name}")
            for e in errors:
                print(f"  - {e}")
        else:
            print(f"ok   {path.name}")

        rid = rec.get("id")
        if rid in seen_ids:
            hard_failures += 1
            print(f"  - duplicate id {rid} (also in {seen_ids[rid]})")
        elif isinstance(rid, str):
            seen_ids[rid] = path.name

        all_warnings += consistency_checks(rec)
        records.append(rec)

    if all_warnings:
        print("\n--- Warnings ---")
        for w in all_warnings:
            print(f"  ! {w}")

    report_statistics(records)

    print()
    if hard_failures:
        print(f"{hard_failures} record(s) failed validation.")
        return 1
    print("All records passed schema validation.")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
